files.content:
.page::after {
  content: "";
  display: table;
  clear: both;
}

.nav {
  float: left;
  width: 200px;
}

.content {
  float: left;
  width: calc(100% - 440px);
  margin: 0 20px;
}

.aside {
  float: right;
  width: 200px;
}

.footer {
  clear: both;
}

assistant.body:
.page {
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr) 200px;
  grid-template-areas:
    "header header  header"
    "nav    content aside"
    "footer footer  footer";
  gap: 20px;
}

.header { grid-area: header; }
.nav { grid-area: nav; }
.content { grid-area: content; }
.aside { grid-area: aside; }
.footer { grid-area: footer; }
